import 'package:flutter_test/flutter_test.dart';
import 'package:flutter/widgets.dart';
import 'package:project_zion/features/window_manager/core/window_manager.dart';
void main(){test('three windows focus newest and preserve z order',(){final m=WindowManager();final a=m.open(title:'A',content:const SizedBox());final b=m.open(title:'B',content:const SizedBox());final c=m.open(title:'C',content:const SizedBox());expect(m.windows,hasLength(3));expect(m.activeWindowId,c);expect(m.windows.last.id,c);expect(a,isNot(b));});test('closing active focuses remaining top window',(){final m=WindowManager();final a=m.open(title:'A',content:const SizedBox());final b=m.open(title:'B',content:const SizedBox());m.close(b);expect(m.activeWindowId,a);});test('closed window rejects focus and repeated close',(){final m=WindowManager();final id=m.open(title:'A',content:const SizedBox());expect(m.close(id),isTrue);expect(m.close(id),isFalse);expect(m.focus(id),isFalse);});test('same application may have distinct window ids',(){final m=WindowManager();final a=m.open(title:'A',content:const SizedBox(),appKey:'A');final b=m.open(title:'A',content:const SizedBox(),appKey:'A');expect(a,isNot(b));});}